// From episode 1 (Build Your First AI Agent in Java), kept here for comparison.
// It is not compiled: Maven only builds src/main/java.
package agent;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.ContentBlock;
import com.anthropic.models.messages.ContentBlockParam;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.StopReason;
import com.anthropic.models.messages.ToolResultBlockParam;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class MyFirstAgent {

    public static void main(String[] args) {
        // Reads your key from the ANTHROPIC_API_KEY variable
        AnthropicClient client = AnthropicOkHttpClient.fromEnv();

        System.out.print("Ask your agent: ");
        String question = new Scanner(System.in).nextLine();

        // The conversation: model, tools, and the user's question
        MessageCreateParams.Builder chat =
            MessageCreateParams.builder()
                .model("claude-opus-5-5")
                .maxTokens(16000L)
                .addTool(Tools.TIME)
                .addTool(Tools.CALCULATOR)
                .addUserMessage(question);

        // The agent loop
        while (true) {
            Message reply = client.messages().create(chat.build());
            chat.addMessage(reply); // no memory: keep the history

            for (ContentBlock block : reply.content()) {
                block.text().ifPresent(t ->
                        System.out.println("Claude: " + t.text()));
            }

            // No tool requested? Then Claude is done.
            StopReason why = reply.stopReason().orElse(null);
            if (why != StopReason.TOOL_USE) {
                break;
            }

            // Run every tool Claude asked for, send all results back
            List<ContentBlockParam> results = new ArrayList<>();
            for (ContentBlock block : reply.content()) {
                block.toolUse().ifPresent(call -> {
                    String result = Tools.run(call);
                    System.out.println("  [tool] " + call.name()
                            + " -> " + result);
                    results.add(ContentBlockParam.ofToolResult(
                            ToolResultBlockParam.builder()
                                    .toolUseId(call.id())
                                    .content(result)
                                    .build()));
                });
            }
            chat.addUserMessageOfBlockParams(results);
        }
    }
}

package agent;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.ContentBlock;
import com.anthropic.models.messages.ContentBlockParam;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.StopReason;
import com.anthropic.models.messages.TextBlock;
import com.anthropic.models.messages.Tool;
import com.anthropic.models.messages.ToolResultBlockParam;
import com.anthropic.models.messages.ToolUseBlock;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;

// One agent = its own system prompt, its own tools, its own context
public class Agent {

    // Reads your key from the ANTHROPIC_API_KEY variable
    private static final AnthropicClient CLIENT =
            AnthropicOkHttpClient.fromEnv();

    private final String name;
    private final String systemPrompt;
    private final List<Tool> tools;
    private final Function<ToolUseBlock, String> toolRunner;

    public Agent(String name, String systemPrompt, List<Tool> tools,
                 Function<ToolUseBlock, String> toolRunner) {
        this.name = name;
        this.systemPrompt = systemPrompt;
        this.tools = tools;
        this.toolRunner = toolRunner;
    }

// The agent loop from episode 1, wrapped in one method
public String run(String task) {
    System.out.println("[" + name + "] working...");

    // A fresh conversation: this agent sees only its own task
    MessageCreateParams.Builder chat =
        MessageCreateParams.builder()
            .model("claude-opus-5-5")
            .maxTokens(16000L)
            .system(systemPrompt)
            .addUserMessage(task);
    tools.forEach(chat::addTool);

    for (int turn = 0; turn < 10; turn++) {
        Message reply = CLIENT.messages().create(chat.build());
        chat.addMessage(reply);

        // No tool requested? Return the agent's answer.
        StopReason why = reply.stopReason().orElse(null);
        if (why != StopReason.TOOL_USE) {
            return reply.content().stream()
                    .flatMap(block -> block.text().stream())
                    .map(TextBlock::text)
                    .collect(Collectors.joining("\n"));
        }

            // Run every tool it asked for, send all results back
            List<ContentBlockParam> results = new ArrayList<>();
            for (ContentBlock block : reply.content()) {
                block.toolUse().ifPresent(call -> {
                    System.out.println("  [" + name + "] tool: "
                            + call.name());
                    results.add(ContentBlockParam.ofToolResult(
                            ToolResultBlockParam.builder()
                                    .toolUseId(call.id())
                                    .content(toolRunner.apply(call))
                                    .build()));
                });
            }
            chat.addUserMessageOfContentBlockParams(results);
        }
        return "Stopped: too many turns";
    }
}

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;

// Sample code to review (it has bugs on purpose)
public class UserService {

    private final Connection db;

    public UserService(Connection db) {
        this.db = db;
    }

    public boolean isAdmin(String username) throws SQLException {
        Statement st = db.createStatement();
        ResultSet rs = st.executeQuery(
            "SELECT role FROM users WHERE name = '" + username + "'");
        if (rs.next()) {
            return rs.getString("role") == "ADMIN";
        }
        return false;
    }
}

package agent;

import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.Tool;
import com.anthropic.models.messages.ToolUseBlock;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

    // Plain Java: the real work, safe to test without an API key
    static String readFile(String name) {
        try {
            Path file = Path.of("sample", name).normalize();
            if (!file.startsWith("sample")) {
                return "Error: only files in the sample folder";
            }
            return Files.readString(file);
        } catch (Exception e) {
            return "Error: cannot read " + name;
        }
    }

    // Run the tool call the agent asked for
    @SuppressWarnings("unchecked")
    static String run(ToolUseBlock call) {
        Map<String, Object> in = call._input().convert(Map.class);
        return readFile((String) in.get("name"));
    }
}

package agent;

import java.util.List;

// Two agents, two jobs: one finds the bugs, one explains them
public class ReviewTeam {

    public static void main(String[] args) {
        // Agent 1: can read files. Its only job is to find real bugs.
        Agent reviewer = new Agent("Reviewer",
                "You are a senior Java reviewer. Read the file "
                + "with your tool. List real bugs only: "
                + "line, problem, fix.",
                List.of(FileTools.READ_FILE), FileTools::run);

        // Agent 2: no tools. It never sees the code, only the notes.
        Agent writer = new Agent("Writer",
                "You turn code review notes into a short, friendly "
                + "report for a junior developer. Max 8 lines.",
                List.of(), call -> "Error: no tools");

        String notes = reviewer.run("Review UserService.java");
        String report = writer.run("Write the report:\n" + notes);

        System.out.println("\n=== REPORT ===\n" + report);
    }
}
